create table if not exists blog.telegram_users (
  id uuid primary key default gen_random_uuid(), telegram_user_id bigint not null unique, display_name text not null default '', role text not null default 'owner' check (role in ('owner','admin','editor')), is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now()
);
create table if not exists blog.telegram_actions (
  id uuid primary key default gen_random_uuid(), telegram_user_id bigint not null, update_id bigint not null unique, command text, action text not null, entity_type text, entity_id uuid, status text not null default 'processing' check (status in ('processing','succeeded','failed','ignored')), request_payload jsonb not null default '{}'::jsonb, result_payload jsonb not null default '{}'::jsonb, error_message text, created_at timestamptz not null default now()
);
create index if not exists blog_telegram_actions_user_created_idx on blog.telegram_actions(telegram_user_id,created_at desc);
create index if not exists blog_telegram_actions_status_created_idx on blog.telegram_actions(status,created_at desc);
create table if not exists blog.telegram_sessions (telegram_user_id bigint primary key,state text not null,context jsonb not null default '{}'::jsonb,expires_at timestamptz not null,updated_at timestamptz not null default now());
create index if not exists blog_telegram_sessions_expires_idx on blog.telegram_sessions(expires_at);
create table if not exists blog.subscribers (
 id uuid primary key default gen_random_uuid(),email text not null,email_normalized text generated always as(lower(btrim(email))) stored,status text not null default 'pending' check(status in('pending','active','unsubscribed','bounced','complained')),source text not null default 'website',consent_at timestamptz not null default now(),confirmed_at timestamptz,unsubscribed_at timestamptz,confirm_token_hash text,unsubscribe_token_hash text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint subscribers_email_shape check(email_normalized ~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'));
create unique index if not exists blog_subscribers_email_unique on blog.subscribers(email_normalized);
create unique index if not exists blog_subscribers_confirm_token_unique on blog.subscribers(confirm_token_hash) where confirm_token_hash is not null;
create unique index if not exists blog_subscribers_unsubscribe_token_unique on blog.subscribers(unsubscribe_token_hash) where unsubscribe_token_hash is not null;
create index if not exists blog_subscribers_status_created_idx on blog.subscribers(status,created_at desc);
create table if not exists blog.newsletter_campaigns (id uuid primary key default gen_random_uuid(),subject text not null,preheader text not null default '',content_html text not null default '',content_text text not null default '',status text not null default 'draft' check(status in('draft','scheduled','sending','sent','failed','cancelled')),scheduled_at timestamptz,sent_at timestamptz,created_by uuid references auth.users(id) on delete set null,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists blog_newsletter_campaigns_status_schedule_idx on blog.newsletter_campaigns(status,scheduled_at);
create table if not exists blog.newsletter_deliveries (id uuid primary key default gen_random_uuid(),campaign_id uuid not null references blog.newsletter_campaigns(id) on delete cascade,subscriber_id uuid not null references blog.subscribers(id) on delete cascade,provider_message_id text,status text not null default 'pending' check(status in('pending','sent','delivered','opened','clicked','bounced','complained','failed','skipped')),sent_at timestamptz,error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(campaign_id,subscriber_id));
create index if not exists blog_newsletter_deliveries_campaign_status_idx on blog.newsletter_deliveries(campaign_id,status);
create index if not exists blog_newsletter_deliveries_subscriber_idx on blog.newsletter_deliveries(subscriber_id,created_at desc);
create index if not exists blog_newsletter_deliveries_provider_idx on blog.newsletter_deliveries(provider_message_id) where provider_message_id is not null;
create table if not exists blog.contact_messages (id uuid primary key default gen_random_uuid(),name text not null,email text not null,subject text not null,message text not null,status text not null default 'new' check(status in('new','read','replied','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),constraint contact_email_shape check(email ~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$'),constraint contact_name_len check(char_length(name) between 1 and 120),constraint contact_subject_len check(char_length(subject) between 1 and 240),constraint contact_message_len check(char_length(message) between 1 and 10000));
create index if not exists blog_contact_messages_status_created_idx on blog.contact_messages(status,created_at desc);
create table if not exists blog.automation_rules (id uuid primary key default gen_random_uuid(),event text not null check(event in('post.published','post.scheduled','post.failed','contact.received','newsletter.subscribed')),action text not null check(action in('telegram.notify_owner','telegram.post_channel','newsletter.send_article')),config jsonb not null default '{}'::jsonb,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists blog_automation_rules_event_active_idx on blog.automation_rules(event,is_active);
create table if not exists blog.automation_runs (id uuid primary key default gen_random_uuid(),rule_id uuid not null references blog.automation_rules(id) on delete cascade,event text not null,entity_id uuid,idempotency_key text not null,status text not null default 'processing' check(status in('processing','succeeded','failed','skipped')),attempt_count integer not null default 1 check(attempt_count between 1 and 10),next_retry_at timestamptz,started_at timestamptz not null default now(),finished_at timestamptz,error_message text,metadata jsonb not null default '{}'::jsonb,unique(rule_id,idempotency_key));
create index if not exists blog_automation_runs_retry_idx on blog.automation_runs(status,next_retry_at) where status='failed';
create index if not exists blog_automation_runs_started_idx on blog.automation_runs(started_at desc);
create table if not exists blog.analytics_events (id bigint generated always as identity primary key,event_name text not null check(event_name in('share_click','copy_link','newsletter_signup','newsletter_confirm','telegram_publish','telegram_channel_post','search_submit')),entity_type text,entity_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists blog_analytics_events_name_created_idx on blog.analytics_events(event_name,created_at desc);
create index if not exists blog_analytics_events_entity_idx on blog.analytics_events(entity_type,entity_id,created_at desc) where entity_id is not null;
create table if not exists blog.telegram_channel_deliveries (id uuid primary key default gen_random_uuid(),post_id uuid not null references blog.posts(id) on delete cascade,channel_id text not null,telegram_message_id bigint,status text not null default 'pending' check(status in('pending','sent','failed')),error_message text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(post_id,channel_id));
create table if not exists blog_private.rate_limits (scope text not null,key_hash text not null,occurred_at timestamptz not null default now());
create index if not exists blog_private_rate_limits_lookup_idx on blog_private.rate_limits(scope,key_hash,occurred_at desc);
alter table blog.site_settings add column if not exists telegram_auto_post_enabled boolean not null default false,add column if not exists telegram_notify_owner_enabled boolean not null default true,add column if not exists newsletter_double_opt_in boolean not null default true,add column if not exists newsletter_auto_send_new_posts boolean not null default false,add column if not exists newsletter_sender_name text not null default 'معتز العلقمي',add column if not exists newsletter_sender_email text,add column if not exists newsletter_reply_to text,add column if not exists newsletter_footer text not null default '';
create trigger blog_telegram_users_updated before update on blog.telegram_users for each row execute function blog_private.set_updated_at();
create trigger blog_subscribers_updated before update on blog.subscribers for each row execute function blog_private.set_updated_at();
create trigger blog_newsletter_campaigns_updated before update on blog.newsletter_campaigns for each row execute function blog_private.set_updated_at();
create trigger blog_newsletter_deliveries_updated before update on blog.newsletter_deliveries for each row execute function blog_private.set_updated_at();
create trigger blog_contact_messages_updated before update on blog.contact_messages for each row execute function blog_private.set_updated_at();
create trigger blog_automation_rules_updated before update on blog.automation_rules for each row execute function blog_private.set_updated_at();
create trigger blog_telegram_channel_deliveries_updated before update on blog.telegram_channel_deliveries for each row execute function blog_private.set_updated_at();
alter table blog.telegram_users enable row level security;alter table blog.telegram_actions enable row level security;alter table blog.telegram_sessions enable row level security;alter table blog.subscribers enable row level security;alter table blog.newsletter_campaigns enable row level security;alter table blog.newsletter_deliveries enable row level security;alter table blog.contact_messages enable row level security;alter table blog.automation_rules enable row level security;alter table blog.automation_runs enable row level security;alter table blog.analytics_events enable row level security;alter table blog.telegram_channel_deliveries enable row level security;
revoke all on blog.telegram_users,blog.telegram_actions,blog.telegram_sessions,blog.subscribers,blog.newsletter_campaigns,blog.newsletter_deliveries,blog.contact_messages,blog.automation_rules,blog.automation_runs,blog.analytics_events,blog.telegram_channel_deliveries from anon,authenticated;
grant select,insert,update,delete on blog.telegram_users,blog.newsletter_campaigns,blog.automation_rules to authenticated;grant select on blog.telegram_actions,blog.telegram_sessions,blog.newsletter_deliveries,blog.automation_runs,blog.analytics_events,blog.telegram_channel_deliveries to authenticated;grant select,update on blog.subscribers,blog.contact_messages to authenticated;grant select,insert,update on blog.newsletter_deliveries,blog.automation_runs,blog.telegram_channel_deliveries to authenticated;grant insert on blog.analytics_events to authenticated;
create policy blog_telegram_users_admin_all on blog.telegram_users for all to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role)) with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));
create policy blog_telegram_actions_admin_select on blog.telegram_actions for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_telegram_sessions_admin_select on blog.telegram_sessions for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_subscribers_admin_select on blog.subscribers for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_subscribers_admin_update on blog.subscribers for update to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role)) with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_campaigns_staff_select on blog.newsletter_campaigns for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role,'editor'::blog.app_role));create policy blog_campaigns_staff_insert on blog.newsletter_campaigns for insert to authenticated with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role,'editor'::blog.app_role) and created_by=(select auth.uid()));create policy blog_campaigns_staff_update on blog.newsletter_campaigns for update to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role,'editor'::blog.app_role)) with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role,'editor'::blog.app_role));create policy blog_campaigns_admin_delete on blog.newsletter_campaigns for delete to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_deliveries_staff_select on blog.newsletter_deliveries for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role,'editor'::blog.app_role));create policy blog_deliveries_staff_write on blog.newsletter_deliveries for all to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role)) with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_contact_admin_select on blog.contact_messages for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_contact_admin_update on blog.contact_messages for update to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role)) with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_automation_rules_admin_all on blog.automation_rules for all to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role)) with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_automation_runs_admin_select on blog.automation_runs for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_automation_runs_admin_write on blog.automation_runs for insert to authenticated with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_automation_runs_admin_update on blog.automation_runs for update to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role)) with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_analytics_admin_select on blog.analytics_events for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_analytics_authenticated_insert on blog.analytics_events for insert to authenticated with check(true);create policy blog_channel_deliveries_admin_select on blog.telegram_channel_deliveries for select to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));create policy blog_channel_deliveries_admin_write on blog.telegram_channel_deliveries for all to authenticated using(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role)) with check(blog_private.current_app_role() in('owner'::blog.app_role,'admin'::blog.app_role));
create or replace function blog_private.consume_rate_limit(p_scope text,p_identifier text,p_max integer,p_window_seconds integer) returns boolean language plpgsql security definer set search_path='' as $$declare k text:=md5(coalesce(p_identifier,''));c integer;begin delete from blog_private.rate_limits where occurred_at<now()-interval '1 day';select count(*) into c from blog_private.rate_limits where scope=p_scope and key_hash=k and occurred_at>now()-make_interval(secs=>p_window_seconds);if c>=p_max then return false;end if;insert into blog_private.rate_limits(scope,key_hash) values(p_scope,k);return true;end;$$;revoke all on function blog_private.consume_rate_limit(text,text,integer,integer) from public,anon,authenticated;
create or replace function blog.newsletter_subscribe(p_email text,p_source text default 'website',p_confirm_hash text default null,p_unsubscribe_hash text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare normalized text:=lower(btrim(p_email));double_opt boolean;row_id uuid;row_status text;request_ip text:=coalesce(current_setting('request.headers',true)::jsonb->>'x-forwarded-for','unknown');begin if normalized !~ '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or char_length(normalized)>320 then raise exception 'INVALID_EMAIL';end if;if not blog_private.consume_rate_limit('newsletter_signup',request_ip,8,600) then raise exception 'RATE_LIMITED';end if;select newsletter_double_opt_in into double_opt from blog.site_settings where id=true;insert into blog.subscribers(email,status,source,consent_at,confirmed_at,confirm_token_hash,unsubscribe_token_hash) values(normalized,case when coalesce(double_opt,true) then 'pending' else 'active' end,coalesce(nullif(btrim(p_source),''),'website'),now(),case when coalesce(double_opt,true) then null else now() end,p_confirm_hash,p_unsubscribe_hash) on conflict(email_normalized) do update set status=case when blog.subscribers.status in('unsubscribed','bounced','complained') then blog.subscribers.status else blog.subscribers.status end,confirm_token_hash=case when blog.subscribers.status='pending' then excluded.confirm_token_hash else blog.subscribers.confirm_token_hash end,unsubscribe_token_hash=coalesce(blog.subscribers.unsubscribe_token_hash,excluded.unsubscribe_token_hash),updated_at=now() returning id,status into row_id,row_status;insert into blog.analytics_events(event_name,entity_type,entity_id,metadata) values('newsletter_signup','subscriber',row_id,jsonb_build_object('source',coalesce(p_source,'website')));return jsonb_build_object('id',row_id,'status',row_status,'double_opt_in',coalesce(double_opt,true));end;$$;
create or replace function blog.newsletter_confirm(p_token_hash text) returns boolean language plpgsql security definer set search_path='' as $$declare sid uuid;begin update blog.subscribers set status='active',confirmed_at=coalesce(confirmed_at,now()),confirm_token_hash=null,updated_at=now() where confirm_token_hash=p_token_hash and status='pending' returning id into sid;if sid is null then return false;end if;insert into blog.analytics_events(event_name,entity_type,entity_id) values('newsletter_confirm','subscriber',sid);return true;end;$$;
create or replace function blog.newsletter_unsubscribe(p_token_hash text) returns boolean language plpgsql security definer set search_path='' as $$begin update blog.subscribers set status='unsubscribed',unsubscribed_at=now(),updated_at=now() where unsubscribe_token_hash=p_token_hash and status<>'unsubscribed';return found;end;$$;
create or replace function blog.contact_submit(p_name text,p_email text,p_subject text,p_message text,p_honeypot text default '') returns uuid language plpgsql security definer set search_path='' as $$declare request_ip text:=coalesce(current_setting('request.headers',true)::jsonb->>'x-forwarded-for','unknown');mid uuid;begin if coalesce(p_honeypot,'')<>'' then raise exception 'SPAM_REJECTED';end if;if char_length(btrim(p_name)) not between 1 and 120 or char_length(btrim(p_subject)) not between 1 and 240 or char_length(btrim(p_message)) not between 1 and 10000 then raise exception 'INVALID_INPUT';end if;if p_email !~* '^[^[:space:]@]+@[^[:space:]@]+[.][^[:space:]@]+$' or char_length(p_email)>320 then raise exception 'INVALID_EMAIL';end if;if not blog_private.consume_rate_limit('contact',request_ip,5,900) then raise exception 'RATE_LIMITED';end if;insert into blog.contact_messages(name,email,subject,message) values(btrim(p_name),lower(btrim(p_email)),btrim(p_subject),btrim(p_message)) returning id into mid;return mid;end;$$;
create or replace function blog.record_public_event(p_event_name text,p_entity_type text default null,p_entity_id uuid default null,p_metadata jsonb default '{}'::jsonb) returns boolean language plpgsql security definer set search_path='' as $$declare request_ip text:=coalesce(current_setting('request.headers',true)::jsonb->>'x-forwarded-for','unknown');begin if p_event_name not in('share_click','copy_link','search_submit') then return false;end if;if not blog_private.consume_rate_limit('analytics_event',request_ip,120,60) then return false;end if;insert into blog.analytics_events(event_name,entity_type,entity_id,metadata) values(p_event_name,p_entity_type,p_entity_id,coalesce(p_metadata,'{}'::jsonb)-'email'-'name'-'token');return true;end;$$;
revoke all on function blog.newsletter_subscribe(text,text,text,text),blog.newsletter_confirm(text),blog.newsletter_unsubscribe(text),blog.contact_submit(text,text,text,text,text),blog.record_public_event(text,text,uuid,jsonb) from public;grant execute on function blog.newsletter_subscribe(text,text,text,text),blog.newsletter_confirm(text),blog.newsletter_unsubscribe(text),blog.contact_submit(text,text,text,text,text),blog.record_public_event(text,text,uuid,jsonb) to anon,authenticated;
select cron.schedule('blog-phase4-cleanup','17 * * * *',$$delete from blog.telegram_sessions where expires_at<now();delete from blog_private.rate_limits where occurred_at<now()-interval '1 day';$$) where not exists(select 1 from cron.job where jobname='blog-phase4-cleanup');
